// O nó anterior ("Resolver Hangar") rodou scripts/identificar-hangar.js, que
// lê o mapeamento grupo de WhatsApp -> hangar de config/hangares.json.
//
// Antes essa tabela era um objeto GRUPO_PARA_HANGAR escrito à mão AQUI, e o
// comentário mandava "adicionar uma linha aqui E uma entrada em
// config/hangares.json". Duas fontes para a mesma verdade — foi exatamente
// esse tipo de duplicação que deixou produção rodando com seletores de slider
// quebrados por semanas. Agora cadastrar um hangar é mexer em UM lugar só:
// config/hangares.json (campo grupoWhatsappId).
const stdout = $input.item.json.stdout || '';
const linhas = stdout.trim().split('\n').filter(Boolean);
const ultimaLinha = linhas[linhas.length - 1];

if (!ultimaLinha) {
  throw new Error('identificar-hangar.js não retornou nada em stdout.');
}

const resultado = JSON.parse(ultimaLinha);

// O Execute Command devolve só o stdout do script, então a mensagem original
// do WhatsApp (ticket, opcao, placa...) precisa ser buscada no nó do webhook.
const webhook = $('WebhookWhatsApp').item.json;
const body = webhook.body || webhook;

if (resultado.status !== 'hangar_identificado') {
  throw new Error(resultado.mensagem || `Não foi possível identificar o hangar do grupo "${body.grupoId}".`);
}

return {
  json: {
    ...body,
    hangarId: resultado.hangarId,
    // guardado para auditoria: diz se o hangar veio do grupo de WhatsApp ou
    // do atalho de teste manual (hangarId direto no corpo da requisição)
    hangarOrigem: resultado.origem,
  },
};

// Os scripts imprimem UM json por linha em stdout (console.log). Pega a última linha não-vazia.
const stdout = $input.item.json.stdout || '';
const linhas = stdout.trim().split('\n').filter(Boolean);
const ultimaLinha = linhas[linhas.length - 1];

let resultado;
if (!ultimaLinha) {
  resultado = {
    status: 'erro',
    mensagem: 'O script não retornou nenhuma saída (stdout vazio).',
    mensagemWhatsapp: '⚠️ Erro interno ao processar o ticket. Nossa equipe foi avisada.',
    notificarAdmin: true,
  };
} else {
  try {
    resultado = JSON.parse(ultimaLinha);
  } catch (erro) {
    resultado = {
      status: 'erro',
      mensagem: `Não consegui interpretar a saída do script: ${ultimaLinha}`,
      mensagemWhatsapp: '⚠️ Erro interno ao processar o ticket. Nossa equipe foi avisada.',
      notificarAdmin: true,
    };
  }
}

if (!resultado.mensagemWhatsapp) {
  resultado.mensagemWhatsapp = '⚠️ Não conseguimos processar essa solicitação. Nossa equipe foi avisada.';
  resultado.notificarAdmin = true;
}

return { json: resultado };
